/* pad_map: a controller's layout, as SDL_GameControllerDB writes it, read into the engine's positional
 * buttons. The Windows and Linux hosts read devices that are not XInput or a known gamepad driver as
 * raw buttons, axes and hats; this says which of those is the south button, the left stick, and so on.
 * The device table (pad_db_windows.h, pad_db_linux.h) is generated by tools/nshvc-padmap. */
#ifndef NSHVC_PAD_MAP_H
#define NSHVC_PAD_MAP_H
#include <stddef.h>
#include <stdint.h>
#include "host.h"

enum { PAD_SRC_NONE, PAD_SRC_BUTTON, PAD_SRC_AXIS, PAD_SRC_HAT };

/* where one of the engine's inputs comes from on the raw device: button `index`; axis `index`
   (half 1 its positive half, 2 its negative, invert flips it); or hat `index`'s direction `mask`
   (1 up, 2 right, 4 down, 8 left) */
typedef struct pad_src {
    uint8_t kind, mask, half, invert;
    int16_t index;
} pad_src;

/* btn[] by host_pad button bit (0 A ... 11 RT, 12-15 d-pad); lt and rt are read from btn[10] and
   btn[11] */
typedef struct pad_map {
    pad_src btn[16];
    pad_src lx, ly, rx, ry;
    char    name[64];
} pad_map;

/* the table's entry for the device: vendor and product, and the device's version when it has one
   (version < 0 when not); one with the same version wins over another of that vendor and product.
   1 and *m filled when found */
int pad_map_find(const char *const *db, size_t count, unsigned vendor, unsigned product, int version, pad_map *m);

/* a device's state as read: buttons, axes -1..1 (y positive downward), hats as direction masks */
typedef struct pad_raw {
    const unsigned char *buttons;
    int                  nbuttons;
    const float         *axes;
    int                  naxes;
    const unsigned char *hats;
    int                  nhats;
} pad_raw;

/* o's sticks, triggers and buttons from the raw state through the map */
void pad_map_apply(const pad_map *m, const pad_raw *r, host_pad *o);

/* the controller family by USB vendor (HOST_PAD_*) */
int pad_style_of_vendor(unsigned vendor);

/* an identity from a text: FNV-1a, never 0 */
uint64_t pad_hash(const char *text);
#endif
